  f.onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(f)),invoice=r.invoices.find(i=>i.id===b.invoice_id),amount=Number(b.amount),remaining=invoice?Math.max(0,(Number(invoice.amount_paise)||0)-paid(invoice.id)):0;if(!invoice){status('Choose a valid fee / instalment.');return}if(!Number.isFinite(amount)||amount<=0){status('Enter a valid payment amount.');return}if(Math.round(amount*100)>remaining){status('Payment cannot exceed the outstanding balance of '+money(remaining)+'.');return}if(b.date>today()){status('Received date cannot be in the future.');return}e.submitter.disabled=true;try{b.amount_paise=Math.round(amount*100);delete b.amount;b.request_id=request;await call('payments','POST',b);request=crypto.randomUUID();await refresh();status('✓ Payment recorded. Official receipt number has been generated and the Ledger updated automatically.')}catch(err){status(err.message);e.submitter.disabled=false}};return;
