  area.innerHTML=`<span class="eyebrow word-colors"><i>HEAD OFFICE</i> <i>·</i> LEDGER</span><h3>Head Office Balance</h3><p>Generate a prefilled challan, deposit at the bank, then submit the bank reference. The balance increases only after Head Office verifies the bank credit.</p><div class="portal-grid"><article class="portal-card"><p>Available for spot kit orders</p><strong class="metric">${money(balance)}</strong></article><article class="portal-card"><p>Deposits awaiting confirmation</p><strong class="metric">${deposits.filter(x=>x.status==='Pending').length}</strong></article></div>${banks.length?`<h3>Verified Head Office accounts</h3><div class="portal-grid">${banks.map(a=>`<article class="portal-card"><h4>${esc(a.label||a.bank_name)}</h4><p>${esc(a.beneficiary_name)} · ${esc(a.bank_name)} · ${esc(a.branch)}</p><p>${esc(a.account_type)} A/C ${esc(a.account_number)} · IFSC ${esc(a.ifsc)}</p>${a.upi_id?`<p>UPI: ${esc(a.upi_id)}</p>`:''}${/^data:image\/(?:png|jpeg|webp);base64,[A-Za-z0-9+/]+={0,2}$/.test(a.qr_data_uri||'')?`<img src="${esc(a.qr_data_uri)}" alt="Verified payment QR for ${esc(a.label||a.bank_name)}" style="width:140px;max-width:100%;height:auto">`:''}</article>`).join('')}</div><details class="portal-editor" open><summary>Generate prefilled bank challan</summary><form id="centerDepositForm"><div class="fields">${select('bank_account_id','1. Head Office account',banks.map(a=>[a.id,(a.label||a.bank_name)+' · '+a.bank_name+' · ending '+String(a.account_number).slice(-4)]))}${select('payment_mode','Payment method',['Cash deposit','NEFT','RTGS','IMPS','UPI'])}<label>Amount to deposit (INR)<input name="amount" type="number" min="0.01" step="0.01" required></label>${input('purpose','Purpose / remarks')}${input('depositor_name','Depositor name')}${input('depositor_mobile','Depositor mobile')}<label>Remitter bank (for NEFT/RTGS)<input name="remitter_bank" maxlength="160"></label><label>Remitter account (if applicable)<input name="remitter_account" inputmode="numeric" maxlength="24"></label></div><p>Verify the selected account before paying. UPI is available only for accounts with a verified UPI ID and QR. Bank credit is confirmed by Head Office after deposit.</p><button>Generate challan</button></form></details>`:'<article class="portal-card"><h3>Bank details pending</h3><p>Head Office must configure and verify a beneficiary account before a challan can be generated.</p></article>'}<h3>Challans & deposit tracking</h3><div class="portal-grid">${deposits.map(x=>`<article class="portal-card"><strong>${esc(x.deposit_no)}</strong><p>${esc(x.challan_date||x.payment_date||'')} · ${esc(x.payment_mode)} · ${money(x.amount_paise)}</p><p>Status: <strong>${esc(x.status)}</strong>${x.receipt_no?' · Receipt '+esc(x.receipt_no):''}</p>${x.submitted_reference?'<p>Bank reference '+esc(x.submitted_reference)+'</p>':''}${x.review_note?'<p>'+esc(x.review_note)+'</p>':''}${x.bank_snapshot?'<button type="button" class="secondary" data-print-challan="'+esc(x.id)+'">Print / Save PDF</button>':''}${x.status==='Generated'?'<button type="button" data-submit-challan="'+esc(x.id)+'">I deposited this amount</button><div data-challan-extra="'+esc(x.id)+'"></div>':''}</article>`).join('')||'<p class="portal-empty">No challans generated yet.</p>'}</div><h3>Advance account transactions</h3><div class="portal-grid">${entries.map(x=>`<article class="portal-card"><p>${esc(x.date)} · ${esc(x.reference)} · ${esc(x.source_kind)}</p><strong>${x.direction==='CREDIT'?'↓ Credit':'↑ Debit'} ${money(x.amount_paise)}</strong><p>${esc(x.description)}</p></article>`).join('')||'<p class="portal-empty">No confirmed credit or order debit yet.</p>'}</div>`;
  const f=area.querySelector('#centerDepositForm');if(f){let request=crypto.randomUUID();if(banks.length===1)f.elements.bank_account_id.value=banks[0].id;f.onsubmit=async e=>{e.preventDefault();const button=e.submitter,body=Object.fromEntries(new FormData(f));body.amount_paise=Math.round(Number(body.amount)*100);delete body.amount;body.request_id=request;if(body.payment_mode==='UPI'&&!banks.find(a=>a.id===body.bank_account_id&&a.upi_id&&a.qr_data_uri)){status('Choose a verified QR-enabled account for UPI.');return}button.disabled=true;try{await call('center_deposits','POST',body);request=crypto.randomUUID();await refresh();status('✓ Challan generated. Print it, deposit the amount, then submit the bank reference.')}catch(err){status(err.message);button.disabled=false}}}
